                    const id = e.nodeId;
                    body.appendChild(SE.button({ label: 'Im Evolutionsbaum ansehen', icon: SE.uiIcon('evolution'), cls: 'btn btn-small btn-ghost', onClick: () => this.onOpenNode?.(id) }));
