            const histWrap = SE.make('div', 'hist-layout');
            hist.body.appendChild(histWrap);
            this.historyPanel = new SE.HistoryPanel(histWrap, this.history);
            // Report
            const report = this.windows.create({ id: 'report', title: 'Bericht', icon: SE.uiIcon('report'), x: 0.24, y: 0.06, width: 580, height: 680 });
            const reportBody = SE.make('div', 'report-body');
            report.body.appendChild(reportBody);
